import{_ as r,l as i,o as e,c as n,v as t,p as s,x as o,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"资本监管与巴塞尔","description":"","frontmatter":{"title":"资本监管与巴塞尔","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/basel-capital.md","filePath":"econ/basel-capital.md","lastUpdated":1789023840000}'),A={name:"econ/basel-capital.md"};function c(B,a,h,m,_,f){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="资本监管与巴塞尔" tabindex="-1">资本监管与巴塞尔 <a class="header-anchor" href="#资本监管与巴塞尔" aria-label="Permalink to &quot;资本监管与巴塞尔&quot;">​</a></h1><div class="epigraph"><p>最后贷款人管的是挤兑时的现金；资本管的是亏损归谁。把两者写成同一个比率，监管就失去牙齿。</p><footer>—— 据 Basel Committee on Banking Supervision, International Convergence of Capital Measurement and Capital Standards, 1988 及后续框架整理</footer></div><p><a href="/econ/too-big-to-fail">上一课</a>（太大而不能倒）。<a href="/econ/lender-of-last-resort">最后贷款人</a>。Bagehot 已经把流动性窗口限制在好抵押上；本课缺口是偿付能力本身：若股本可以薄到接近零，再好的抵押规则也会在亏损一来时失效。不重讲挤兑博弈，不问准备金乘数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>银行的转换功能要求杠杆：用短存款去持有长而信息密集的贷款。杠杆放大股权回报，也把损失更快推到存款人与纳税人。存款保险与最后贷款人一旦承诺删掉挤兑均衡，股东就有激励把杠杆加到保险能够覆盖的上限——这是<a href="/econ/moral-hazard">道德风险</a>在银行负债上的版本。市场若相信有隐性担保，私人选择的资本会系统性偏低。</p><p>监管资本的问题因此不是「银行要不要赚钱」，而是：在保险与窗口已经改变激励之后，用哪一种可审计的比率把亏损先分配给能被核销的负债（股权与或有可转债），而不是存款。没有这层，Bagehot 的「好抵押」在资产减记后不再好。</p><p><span class="marginnote">会计资本是账面净资产。监管资本是按巴塞尔定义可计入的工具，再除以风险加权资产。两者都可以与市值资本分叉；危机中分叉最大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>巴塞尔协议把资本写成分子分母两套定义。Basel I（1988）用风险加权资产（RWA）：表内资产按类别赋权，表外给信用转换，资本对 RWA 设最低比率。它第一次把国际银行的资本比较从「杠杆倍数」推进到「按风险加权的杠杆」。Basel II 把信用风险权重交给内部模型，引入支柱二（监督检视）与支柱三（披露）。Basel III 在危机后加回更高的普通股核心、资本缓冲、杠杆率（不再只信 RWA）与流动性覆盖——流动性覆盖是对 Diamond–Dybvig 提取的数量约束，资本缓冲才是对偿付的约束。</p><p>比率的经济学含义是损失吸收顺序。普通股先亏；其后是其他一级、二级工具；存款与优先债权在监管意义上不被当作资本。风险权重试图让「同样一单位资本」对应可比较的意外损失，但权重是规则而不是<a href="/econ/stochastic-discount-factor">随机折现因子</a>：它不定价，只限制可持有的暴露。</p>',10)),(e(),s(d,null,{default:o(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOSS%5B%22%E8%B5%84%E4%BA%A7%E4%BA%8F%E6%8D%9F%22%5D%20--%3E%20EQ%5B%22%E6%99%AE%E9%80%9A%E8%82%A1%E5%90%B8%E6%94%B6%22%5D%0A%20%20EQ%20--%3E%20OTHER%5B%22%E5%85%B6%E4%BB%96%E7%9B%91%E7%AE%A1%E8%B5%84%E6%9C%AC%22%5D%0A%20%20OTHER%20--%3E%20DEP%5B%22%E5%AD%98%E6%AC%BE%E4%B8%8E%E7%BA%B3%E7%A8%8E%E4%BA%BA%22%5D%0A%20%20RWA%5B%22%E9%A3%8E%E9%99%A9%E5%8A%A0%E6%9D%83%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20RATIO%5B%22%E8%B5%84%E6%9C%AC%20%2F%20RWA%22%5D%0A%20%20LEV%5B%22%E6%9D%A0%E6%9D%86%E7%8E%87%22%5D%20--%3E%20RATIO2%5B%22%E8%B5%84%E6%9C%AC%20%2F%20%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20LOLR%5B%22%E6%9C%80%E5%90%8E%E8%B4%B7%E6%AC%BE%E4%BA%BA%22%5D%20--%3E%20LIQ%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%2C%20%E9%9D%9E%E8%B5%84%E6%9C%AC%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/econ/reserve-endogenous-money">内生货币</a>的衔接：资本比准备金更硬地限制贷款创造。盯利率时准备金可以再供给，普通股不能在一周内再供给。因此资本是内生货币的数量阀，准备金是结算阀。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是外部性的数量管制。银行倒闭的社会成本大于股东损失：支付体系中断、挤兑传染、处置的财政或有。私人最优资本低于社会最优。最低资本把杠杆的可行集切开，使股东在扩张风险加权暴露时必须先找到能吸收损失的资金。缓冲（conservation / countercyclical）把「刚好踩线」改成「线上方还有一层」，避免亏损立刻触发监管干预下的信贷紧缩。</p><p>风险加权的代价是监管套利：把风险赶到权重低估的暴露上，RWA 下降而真实杠杆不降。杠杆率作为不加权的后盾，正是承认权重会被操纵。这并不使资本变成「银行的成本之源」——下一课 <a href="/econ/modigliani-miller">MM</a> 要问：若市场完全，用股本替换存款不应提高加权资本成本。巴塞尔把股本当成稀缺，已经预设了某种摩擦；摩擦要到权衡与优序才展开。</p><h3 id="分子-什么东西算资本" tabindex="-1">分子：什么东西算资本 <a class="header-anchor" href="#分子-什么东西算资本" aria-label="Permalink to &quot;分子：什么东西算资本&quot;">​</a></h3><p>普通股与留存收益是无可争议的损失吸收：可以核销、可以停股利。优先股、次级债、或有可转债能否计入，取决于它们在持续经营时是否真能减记。Basel III 收紧分子，正是因为危机中许多「二级资本」在需要时仍像债务。本课不记各类工具的合格标准表，只保留顺序：能在倒闭前吸收损失的，才是资本；能在倒闭后参与清算的，是债。存款保险覆盖的存款永远不是资本。</p><p><span class="marginnote">风险权重是规则，不是 SDF。给按揭 50%、给主权 0%，是委员会的选择，不是市场 beta。用监管资本比率当定价模型，会与下一单元的资产定价语言打架。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把流动性覆盖比率（LCR）叫成资本充足。LCR 管的是高流动性资产对净流出，是 Bagehot 的事前库存；资本管的是亏损归谁。也不要用危机中的市值暴跌反推「监管资本没用」：监管用的是会计与规则资本，市值资本另有信息，两者本课不混成一个数字。</p><p>本课不推导 MM 命题，不写税收与破产成本。银行资本为什么在实务上显得贵，是公司金融单元的第一问。宏观审慎的逆周期缓冲只点到为止，不开新的周期模型。</p><p>内部模型（Basel II 支柱一）把分母交给银行自己估。这降低了「一刀切权重」的粗糙，也把模型风险引进监管比率。危机后的杠杆率与输出地板，是对「RWA 可以被做小」的回应。本课停留在：资本是数量阀；阀的刻度会被博弈。</p><p>后课默认：资本是损失吸收顺序与数量阀，LCR 不是资本。银行股本看起来贵，已经离开无摩擦世界——下一课用 MM 给出无关性基准，再谈税、破产与信息。不要把风险权重当成资产定价核。</p><p>普通股先亏。存款保险覆盖的存款不是资本。二级工具危机中若仍像债，就不该计入分子。</p><p>杠杆率是对 RWA 可被做小的后盾。内部模型引入模型风险，输出地板是回应。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保险与 LOLR 改变激励之后，资本把亏损顺序写成可审计比率。</li><li>巴塞尔：分子是损失吸收工具，分母是 RWA，后辅以杠杆率与流动性覆盖。</li><li>资本是内生货币的数量阀；流动性工具不是资本。</li><li>把股本当成贵的，已经离开无摩擦 MM，下一课从那里补。</li><li>出处：BCBS 1988 及 Basel II / III 框架文件。</li></ul>',16))])}const D=r(A,[["render",c]]);export{C as __pageData,D as default};
